// Bellman-Ford Algorithm in C#include <stdio.h>#include <stdlib.h>#define INF 100000int Bellman_Ford(int V, int E, int edge[20][3]) {    int i, u, v, w, k, distance[20], parent[20], S, flag = 1;    // Initialize distances and parents    for (i = 0; i < V; i++) {        distance[i] = INF;        parent[i] = -1;    }    // Take source input    printf("Enter the source vertex (1 to %d): ", V);    scanf("%d", &S);    distance[S - 1] = 0;    // Relax edges V-1 times    for (i = 0; i < V - 1; i++) {        for (k = 0; k < E; k++) {            u = edge[k][0];            v = edge[k][1];            w = edge[k][2];            if (distance[u] != INF && distance[u] + w < distance[v]) {                distance[v] = distance[u] + w;                parent[v] = u;            }        }    }    // Check for negative-weight cycles    for (k = 0; k < E; k++) {        u = edge[k][0];        v = edge[k][1];        w = edge[k][2];        if (distance[u] != INF && distance[u] + w < distance[v]) {            flag = 0;            break;        }    }    // Print results    if (flag) {        printf("\nShortest paths from source vertex %d:\n", S);        for (i = 0; i < V; i++) {            printf("Vertex %d -> Cost = %d, Parent = %d\n", i + 1, distance[i], parent[i] + 1);        }    }    return flag;}int main() {    int V, E, i, edge[20][3];    printf("BELLMAN-FORD ALGORITHM\n");    // Input number of vertices and edges    printf("Enter the number of vertices: ");    scanf("%d", &V);    printf("Enter the number of edges: ");    scanf("%d", &E);    // Input all edges with their weights    printf("Enter edges in the format: <source> <destination> <weight>\n");    for (i = 0; i < E; i++) {        printf("Edge %d: ", i + 1);        scanf("%d %d %d", &edge[i][0], &edge[i][1], &edge[i][2]);        edge[i][0]--;  // Convert to 0-based indexing        edge[i][1]--;    }    // Run Bellman-Ford Algorithm    if (Bellman_Ford(V, E, edge))        printf("\nNo negative weight cycle detected.\n");    else        printf("\nNegative weight cycle exists!\n");return 0;}